-- PostgreSQL reference schema. For local development the app creates this schema via EF Core EnsureCreated.
CREATE TABLE IF NOT EXISTS "Teachers" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "FirstName" varchar(80) NOT NULL, "LastName" varchar(80) NOT NULL,
  "Email" varchar(254) NOT NULL UNIQUE, "Department" varchar(120) NOT NULL
);
CREATE TABLE IF NOT EXISTS "Students" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "FirstName" varchar(80) NOT NULL, "LastName" varchar(80) NOT NULL,
  "Email" varchar(254) NOT NULL UNIQUE, "BirthDate" date NOT NULL, "CreatedAt" timestamptz NOT NULL
);
CREATE TABLE IF NOT EXISTS "Courses" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" varchar(120) NOT NULL, "Description" varchar(2000), "Credits" integer NOT NULL CHECK ("Credits" BETWEEN 1 AND 30),
  "TeacherId" integer NOT NULL REFERENCES "Teachers"("Id") ON DELETE RESTRICT, "CreatedAt" timestamptz NOT NULL
);
CREATE TABLE IF NOT EXISTS "Enrollments" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "StudentId" integer NOT NULL REFERENCES "Students"("Id") ON DELETE CASCADE,
  "CourseId" integer NOT NULL REFERENCES "Courses"("Id") ON DELETE CASCADE,
  "EnrollmentDate" timestamptz NOT NULL, "Grade" numeric(5,2) CHECK ("Grade" BETWEEN 0 AND 100),
  CONSTRAINT "IX_Enrollments_StudentId_CourseId" UNIQUE ("StudentId", "CourseId")
);
INSERT INTO "Teachers" ("FirstName","LastName","Email","Department")
